"use strict";
var pl = GetPlayer();
var debugWin = window.open(undefined, "debug", "width=600,height=800,toolbar=no,location=no");
var debugDoc = debugWin.document;
debugDoc.body.innerHTML = "";
debugDoc.title = "Storyline Debugger";
var refreshButton = debugDoc.createElement("INPUT");
refreshButton.value = "Refresh";
refreshButton.type = "button";
refreshButton.addEventListener("click", refreshVars);
debugDoc.body.appendChild(refreshButton);

// Кнопка для генерации кода сброса
var generateResetCodeButton = debugDoc.createElement("INPUT");
generateResetCodeButton.value = "Generate Reset Code";
generateResetCodeButton.type = "button";
generateResetCodeButton.addEventListener("click", generateResetCode);
debugDoc.body.appendChild(generateResetCodeButton);

var tableElem = debugDoc.createElement("TABLE");
debugDoc.body.appendChild(tableElem);

getStorylineUserVariables(function (slVars) {
    slVars.sort(function(x, y){return x.name > y.name;});
    for (var a = 0; a < slVars.length; a++) {
        var v = slVars[a];
        var trElem = debugDoc.createElement("TR");
        if (a % 2 == 1) trElem.style.backgroundColor = "#dddddd";
        var tdElem = debugDoc.createElement("TD");
        tdElem.innerHTML = v.name;
        tdElem.style.padding = "10px 2px";
        trElem.appendChild(tdElem);
        var inputElem = debugDoc.createElement("INPUT");
        inputElem.storylineVarName = v.name;
        inputElem.defaultValue = v.defaultValue; // Сохраняем стартовое значение

        if (v.type == "number") {
            inputElem.type = "number";
            inputElem.step = undefined;
            inputElem.value = pl.GetVar(v.name);
        } else if (v.type == "boolean") {
            inputElem.type = "checkbox";
            inputElem.checked = pl.GetVar(v.name);
        } else {
            inputElem.type = "text";
            inputElem.value = pl.GetVar(v.name);
        }
        tdElem = debugDoc.createElement("TD");
        tdElem.appendChild(inputElem);
        trElem.appendChild(tdElem);
        tableElem.appendChild(trElem);
    }
});

tableElem.addEventListener("change", function (e) {
    var inputElem = e.target;
    var slVarName = inputElem.storylineVarName;
    var newVal = "";
    if (inputElem.getAttribute("type") == "checkbox") {
        newVal = inputElem.checked;
    } else {
        newVal = inputElem.value;
    }
    pl.SetVar(slVarName, newVal);
});

function refreshVars () {
    var inputs = tableElem.querySelectorAll("input");
    for (var a = 0; a < inputs.length; a++) {
        var elem = inputs[a];
        var val = pl.GetVar(elem.storylineVarName);
        if (elem.type == "checkbox") {
            elem.checked = val;
        } else {
            elem.value = val;
        }
    }
}

// Функция для генерации кода сброса переменных
function generateResetCode() {
    var resetCode = "";
    var inputs = tableElem.querySelectorAll("input");
    for (var a = 0; a < inputs.length; a++) {
        var elem = inputs[a];
        var varName = elem.storylineVarName;
        var defaultValue = elem.defaultValue;
        
        if (elem.type == "checkbox") {
            resetCode += `pl.SetVar("${varName}", ${defaultValue});\n`;
        } else if (elem.type == "number") {
            resetCode += `pl.SetVar("${varName}", ${defaultValue});\n`;
        } else {
            resetCode += `pl.SetVar("${varName}", "${defaultValue}");\n`;
        }
    }

    // Открываем новое окно с кодом сброса
    var codeWin = window.open(undefined, "resetCode", "width=600,height=400,toolbar=no,location=no");
    var codeDoc = codeWin.document;
    codeDoc.body.innerHTML = "<pre>" + resetCode + "</pre>";
    codeDoc.title = "Generated Reset Code";
}

// Функция для получения переменных Storyline
function getStorylineUserVariables(callback) {
    var origGlobalProvideData = window.globalProvideData;
    var scriptElem = document.createElement("SCRIPT");
    scriptElem.src = "html5/data/js/data.js";
    window.globalProvideData = function (foo, data) {
        var dataObj = JSON.parse(data);
        var variableList = [];
        for (var a = 0; a < dataObj.variables.length; a++) {
            var varObj = {name: dataObj.variables[a].name, type: dataObj.variables[a].type, defaultValue: dataObj.variables[a].value};
            if (varObj.name.match(/^[0-9a-zA-Z]{11}_RetryModeInteractionIncompleteOnLoad$/) == null && 
                varObj.name.match(/^LastSlideViewed_[0-9a-zA-Z]{11}$/) == null && 
                varObj.name.match(/^PrintPromptUsername_[0-9a-zA-Z]{11}$/) == null &&
                varObj.name.match(/^PrintPromptWindowQuizVar_[0-9a-zA-Z]{11}$/) == null){
                
                variableList.push(varObj);
            }
        }
        document.body.removeChild(scriptElem);
        window.globalProvideData = origGlobalProvideData;
        callback(variableList);
    }
    document.body.appendChild(scriptElem);
}

function getRandomInRange(min, max, exclude) {
    let randomValue;
    do {
        randomValue = Math.floor(Math.random() * (max - min + 1)) + min;
    } while (randomValue === exclude);
    return randomValue;
}

function assignRandomValues() {
    var player = GetPlayer();
    
    for (var i = 1; i <= 6; i++) {
        let variantName = `Variant_${i}`;
        let currentValue = player.GetVar(variantName);

        if (currentValue === 0) {
            // Если значение равно 0, присваиваем случайное значение
            if (i === 1 || i === 2) {
                player.SetVar(variantName, getRandomInRange(1, 4, null));
            } else {
                player.SetVar(variantName, getRandomInRange(1, 3, null));
            }
        } else {
            // Если значение не равно 0, присваиваем новое случайное значение, отличное от предыдущего
            if (i === 1 || i === 2) {
                player.SetVar(variantName, getRandomInRange(1, 4, currentValue));
            } else {
                player.SetVar(variantName, getRandomInRange(1, 3, currentValue));
            }
        }

        console.log(`${variantName}: ${player.GetVar(variantName)}`); // Отладка
    }
}

// Вызов функции для выполнения задания
assignRandomValues();

// Самовызывающаяся функция для сброса текущих ответов
(function() {
    console.log("[LMS Reset] Начало процесса сброса взаимодействий (SCORM 2004)");

    function getAPI(win) {
        console.log("[LMS Reset] Ищем API_1484_11 (SCORM 2004)");
        var attempts = 0;
        var maxAttempts = 500;

        while (win && attempts < maxAttempts) {
            console.log(`[LMS Reset] Попытка ${attempts + 1} из ${maxAttempts}`);

            try {
                if (win.API_1484_11) {
                    console.log("[LMS Reset] Найден API_1484_11 (SCORM 2004)");
                    return win.API_1484_11;
                }
            } catch (err) {
                console.warn("[LMS Reset] Ошибка доступа к окну:", err);
            }

            attempts++;
            if (win.parent && win.parent !== win) {
                win = win.parent;
            } else {
                break;
            }
        }

        console.error("[LMS Reset] Не удалось найти LMS API после 500 попыток");
        return null;
    }

    function resetInteractions() {
        console.log("[LMS Reset] Начало процесса сброса взаимодействий");

        try {
            // Получаем плеер Storyline
            var player = GetPlayer();
            if (!player) {
                console.error("[LMS Reset] Не удалось получить плеер Storyline");
                return false;
            }
            console.log("[LMS Reset] Плеер Storyline успешно получен");

            // Получаем SCORM 2004 API
            var lmsAPI = getAPI(window);

            if (!lmsAPI) {
                console.error("[LMS Reset] Не удалось найти LMS API");
                player.SetVar("resetStatus", "Не удалось найти LMS API");
                return false;
            } else {
                console.log("[LMS Reset] LMS API успешно получен");
            }

            // Получаем количество взаимодействий
            var interactionCount = parseInt(lmsAPI.GetValue("cmi.interactions._count"), 10) || 0;
            console.log(`[LMS Reset] Найдено взаимодействий: ${interactionCount}`);

            // Проверяем, есть ли взаимодействия для сброса
            if (!interactionCount) {
                console.log("[LMS Reset] Счётчик взаимодействий пуст, сброс не требуется");
                player.SetVar("resetStatus", "Сброс не требуется");
                return true;
            }

            // Сброс всех полей взаимодействий для перезаписи
            for (var j = 0; j < interactionCount; j++) {
                console.log(`[LMS Reset] Обработка взаимодействия ${j}`);

                // Получаем текущее значение
                var currentResponse = lmsAPI.GetValue(`cmi.interactions.${j}.learner_response`);
                console.log(`[LMS Reset] Текущий ответ: ${currentResponse}`);

                // Пробуем разные варианты записи
                var attempts = [
                    "",  // Тестовое значение
                    "{}", // Пустой объект
                    "[]", // Пустой массив
                    " ",  // Пробел
                    "",   // Пустая строка
                    "0"   // Нулевое значение
                ];

                for (var i = 0; i < attempts.length; i++) {
                    var resetValue = attempts[i];
                    console.log(`[LMS Reset] Попытка ${i + 1}: Пробуем установить значение '${resetValue}'`);

                    var success = lmsAPI.SetValue(`cmi.interactions.${j}.learner_response`, resetValue);
                    var errorCode = lmsAPI.GetLastError();

                    if (success === "true" && errorCode === "0") {
                        console.log(`[LMS Reset] Успешно установлено значение '${resetValue}'`);
                        break;
                    } else {
                        console.warn(`[LMS Reset] Не удалось установить значение '${resetValue}'. Код ошибки: ${errorCode}`);
                    }
                }

                // Проверяем, что значение действительно изменилось
                var newResponse = lmsAPI.GetValue(`cmi.interactions.${j}.learner_response`);
                console.log(`[LMS Reset] Новый ответ после сброса: ${newResponse}`);
            }

            // Фиксация изменений
            var commitSuccess = lmsAPI.Commit("");
            if (commitSuccess === "true") {
                console.log("[LMS Reset] Изменения успешно зафиксированы");
                player.SetVar("resetStatus", "Сброс успешен");
            } else {
                console.error("[LMS Reset] Ошибка при фиксации изменений");
                player.SetVar("resetStatus", "Ошибка при сохранении");
            }

            return true;
        } catch (error) {
            console.error("[LMS Reset] Критическая ошибка:", error);
            player.SetVar("resetStatus", "Критическая ошибка при сбросе");
            return false;
        }
    }

    // Немедленный запуск функции
    resetInteractions();
})();
